      "قال الله عز وجل: \"ثُمَّ جَعَلْنَاكَ عَلَى شَرِيعَةٍ مِنَ الْأَمْرِ فَاتَّبِعْهَا وَلَا تَتَّبِعْ أَهْوَاءَ الَّذِينَ لَا يَعْلَمُونَ\".",
      "• التعريف اللغوي: الشرع لغة مصدر \"شَرَعَ\"، ويراد بها الطريق المستقيم لأن لفظ شرع يدل على الإظهار والبيان.",
      "• المعنى الأول: السبيل والسنة أي الطريقة التي تسن بها الأحكام (لِكُلٍّ جَعَلْنَا مِنْكُمْ شِرْعَةً وَمِنْهَاجًا).",
      "• المعنى الثاني: الاختصاص بالتشريع، وهو لله وحده لأنه الحاكم بالحق وغيره باطل.",
      "• الاشتقاق: مشتقة من فعل شَرَعَ (أمر وحدد وأحل، أو منع). وقد أطلق هذا الاسم على مورد المياه الجارية الظاهرة للناس، مما يدل على الوضوح والخلو من الغموض."
