      "• عملها: رقابة وقائية مانعة تتم 'قبل' إصدار القانون ونشره في الجريدة الرسمية ودخوله حيز التنفيذ المادي.",
      "• تقديرها: تمتاز بحماية الدستور مسبقاً وتفادي صدور قوانين معيبة، وتتلائم مع السيادة البرلمانية. لكن يعاب عليها الخضوع للتقلبات والصراعات السياسية والاعتبارات الحزبية، وافتقادها للضمانات القضائية الصارمة لمنفعة المتقاضين.",
      "ثانياً: الرقابة القضائية (اللاحقة والمستقلة):",
      "تُسند مهمة الفصل في دستورية القوانين إلى جهة قضائية مستقلة (إما المحاكم العادية أو محكمة دستورية عليا متخصصة). وتتخذ شكلين رئيسيين:",
      "1. رقابة الدعوى الأصلية (رقابة الإلغاء): تتيح للأفراد رفع طعن ودعوى مباشرة ومستقلة أمام المحكمة الدستورية لإلغاء القانون المخالف، وإذا ثبت عدم دستوريته يقضى بإلغائه كلياً وبأثر عام تجاه الكافة.",
      "2. رقابة الدفع بعدم الدستورية (رقابة الامتناع): تثار بصفة فرعية أثناء نظر قضية موضوعية قائمة أمام القضاء العادي، حيث يدفع أحد الخصوم بعدم دستورية مقتضى قانوني يراد تطبيقه عليه. فإذا تيقنت المحكمة من جدية الدفع، تمتنع عن تطبيق ذلك المقتضى في تلك النازلة المعروضة عليها مع إبقاء القانون سارياً للكافة دون إلغائه."
