      "• تحدي تفعيل ميزة الدفع بعدم الدستورية للأفراد: تطلب هذا الإجراء صدور قانون تنظيمي خاص عرف مساراً تشريعياً عسيراً وقرارات متبادلة لتوضيح مسطرة قبول الدفوع، مما يتطلب تسهيل المساطر والآجال حتى يستفيد المواطن البسيط فعلياً من هذه الضمانة الدستورية الراقية دون تعقيد.",
      "• آفاق المستقبل: يتطلع الفاعلون القانونيون إلى تعزيز استقلال المحكمة وإمكانية الإحالة الذاتية للقضايا، وتفعيل الرقابة الدستورية لتمكين منظومة 'دولة الحق والقانون' من البلوغ التام لغاياتها الديمقراطية."
